// ── Prepare data payload for Claude ──
const commits = $input.all().filter(i => i.json.sha).map(c => ({
  sha: c.json.sha?.substring(0, 7),
  message: c.json.commit?.message?.split('\n')[0] || c.json.message,
  author: c.json.commit?.author?.name || c.json.author?.login,
  date: c.json.commit?.author?.date || c.json.date
}));

const issues = $input.all().filter(i => i.json.title && !i.json.pull_request).map(i => ({
  number: i.json.number,
  title: i.json.title,
  state: i.json.state,
  closed_at: i.json.closed_at,
  user: i.json.user?.login
}));

const prs = $input.all().filter(i => i.json.title && i.json.merged_at).map(p => ({
  number: p.json.number,
  title: p.json.title,
  merged_at: p.json.merged_at,
  user: p.json.user?.login
}));

const lang = $env.SUMMARY_LANGUAGE || 'EN';
const repoName = `${$env.GITHUB_REPO_OWNER}/${$env.GITHUB_REPO_NAME}`;
const weekStart = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
const weekEnd = new Date().toISOString().split('T')[0];

const prompts = {
  EN: `You are a technical writer creating weekly development summaries for software teams. Your tone is professional, encouraging, and clear. Focus on achievements, progress, and team contributions.`,
  FR: `Vous êtes un rédacteur technique créant des résumés de développement hebdomadaires pour les équipes logicielles. Votre ton est professionnel, encourageant et clair. Concentrez-vous sur les réalisations, les progrès et les contributions de l'équipe.`
};

const userMessages = {
  EN: `Generate a weekly development summary for GitHub repository ${repoName}.

## Closed Issues (Past 7 Days)
${JSON.stringify(issues, null, 2)}

## Merged Pull Requests (Past 7 Days)
${JSON.stringify(prs, null, 2)}

## Commits (Past 7 Days)
${JSON.stringify(commits, null, 2)}

Please create a narrative summary that:
1. Highlights key achievements and milestones
2. Summarizes major features or fixes shipped
3. Identifies trends or patterns in development activity
4. Notes any blockers or concerns
5. Celebrates contributor efforts with shout-outs

Format the output in Markdown with emoji sections. Start with a # Weekly Development Summary header, then the repo and date range, then each section.`,
  FR: `Générez un résumé de développement hebdomadaire pour le dépôt GitHub ${repoName}.

## Issues fermées (7 derniers jours)
${JSON.stringify(issues, null, 2)}

## Pull Requests fusionnées (7 derniers jours)
${JSON.stringify(prs, null, 2)}

## Commits (7 derniers jours)
${JSON.stringify(commits, null, 2)}

Créez un résumé narratif qui :
1. Met en évidence les réalisations et jalons clés
2. Résume les principales fonctionnalités ou correctifs livrés
3. Identifie les tendances dans l'activité de développement
4. Note les blocages ou préoccupations
5. Célèbre les contributions des membres de l'équipe

Formatez la sortie en Markdown avec des sections emoji. Commencez par un en-tête # Résumé Hebdomadaire de Développement, puis le dépôt et la plage de dates, puis chaque section.`
};

return {
  system: prompts[lang] || prompts.EN,
  userMessage: userMessages[lang] || userMessages.EN,
  repoName,
  weekStart,
  weekEnd,
  issueCount: issues.length,
  prCount: prs.length,
  commitCount: commits.length
};
